Boolean dei_sc_icon_sensor1_level_update ( Notify_Pld_Sensor_Level level ) 
{
    dei_sc_info_set( DEI_SC_INFO_SENSOR1_LEVEL , level );

    return dei_sc_tx( DEI_SC_ACK_SENSOR_LEVEL_RESET, DEI_SC_NORMAL_TX , 100 ) ; 
}

//--------------------------------------------------------------------------//

Boolean dei_sc_icon_sensor_level_increase ( Notify_Pld_Sensor_Level level )
{
    dei_sc_info_set( DEI_SC_INFO_SENSOR1_LEVEL , level );

    return dei_sc_tx( DEI_SC_ACK_SENSOR1_LEVEL_INCREASE, DEI_SC_NORMAL_TX , 100 ) ; 
}

//--------------------------------------------------------------------------//

Boolean dei_sc_icon_sensor_level_decrease ( Notify_Pld_Sensor_Level level )
{
    dei_sc_info_set( DEI_SC_INFO_SENSOR1_LEVEL , level );

    return dei_sc_tx( DEI_SC_ACK_SENSOR1_LEVEL_DECREASE, DEI_SC_NORMAL_TX , 100 ) ; 
}


